namespace sv_b7377a6a247f4fb085ff4721bf7c865f.Services;

public class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnWarehouseChanged;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }

    public IReadOnlyList<WarehouseInfo> GetWarehouses() =>
    [
        new("WH-001", "Warehouse A - Main Distribution"),
        new("WH-002", "Warehouse B - East Region"),
        new("WH-003", "Warehouse C - West Region"),
        new("WH-004", "Warehouse D - Cold Storage"),
    ];

    public void Dispose()
    {
        OnWarehouseChanged = null;
    }
}

public record WarehouseInfo(string Id, string Name);

namespace sv_b7377a6a247f4fb085ff4721bf7c865f.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling for the current user's circuit.
/// Each Blazor Server circuit gets its own instance, ensuring per-user isolation.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private int _currentAlertCount;

    public int CurrentAlertCount => _currentAlertCount;

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async database call with random result 0-15
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by components to start polling. Uses reference counting so polling
    /// runs as long as at least one subscriber is active.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Called by components when they no longer need updates (e.g., on dispose).
    /// Polling stops when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _cts?.Dispose();
            _cts = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
                _currentAlertCount = count;
                OnAlertCountChanged?.Invoke();

                await Task.Delay(TimeSpan.FromSeconds(10), ct);
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private void HandleWarehouseChanged()
    {
        // When warehouse changes, immediately refresh if polling is active
        if (_subscriberCount > 0)
        {
            _cts?.Cancel();
            _cts?.Dispose();
            _cts = new CancellationTokenSource();
            _ = PollLoopAsync(_cts.Token);
        }
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        _cts?.Cancel();
        _cts?.Dispose();
        OnAlertCountChanged = null;
    }
}

