@rendermode InteractiveServer
@using sv_b7377a6a247f4fb085ff4721bf7c865f.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-select"><strong>Current Warehouse:</strong></label>
    <select id="warehouse-select" class="form-select form-select-sm" @onchange="OnWarehouseSelected">
        @foreach (var wh in _warehouses)
        {
            <option value="@wh.Id" selected="@(wh.Id == WarehouseState.CurrentWarehouseId)">@wh.Name</option>
        }
    </select>
</div>

@code {
    private IReadOnlyList<WarehouseInfo> _warehouses = [];

    protected override void OnInitialized()
    {
        _warehouses = WarehouseState.GetWarehouses();
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            WarehouseState.SetWarehouse(warehouseId);
        }
    }

    private void HandleStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
    }
}

