arguments.file_text:
@page "/dashboard"
@rendermode InteractiveServer
@using sv_b7377a6a247f4fb085ff4721bf7c865f.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@GetCurrentWarehouseName()</p>
                <p class="text-muted">ID: @WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card @(_alertCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 @(_alertCount > 5 ? "text-danger" : "text-success")">
                    @_alertCount
                </p>
                <p class="text-muted">
                    Items below minimum level &bull; Refreshes every 10s
                </p>
            </div>
        </div>
    </div>
</div>

<div class="row">
    <div class="col-12">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p>
                    <span class="badge bg-info">Active</span>
                    Polling for warehouse <strong>@WarehouseState.CurrentWarehouseId</strong>
                </p>
                <p class="text-muted mb-0">
                    Last updated: @_lastUpdated.ToString("HH:mm:ss")
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private int _alertCount;
    private DateTime _lastUpdated = DateTime.Now;

    protected override void OnInitialized()
    {
        _alertCount = AlertService.CurrentAlertCount;

        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;

        // Start polling when this page becomes visible
        AlertService.StartPolling();
    }

    private void HandleAlertCountChanged()
    {
        InvokeAsync(() =>
        {
            _alertCount = AlertService.CurrentAlertCount;
            _lastUpdated = DateTime.Now;
            StateHasChanged();
        });
    }

    private void HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetCurrentWarehouseName()
    {
        var warehouse = WarehouseState.GetWarehouses()
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId);
        return warehouse?.Name ?? "Unknown";
    }

    public void Dispose()
    {
        // Stop polling when the user leaves this page
        AlertService.StopPolling();
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

